"use client";

import { useState } from "react";
import { completePractice, startPractice, submitPractice } from "@/lib/api";
import type {
  PracticeComplete,
  PracticeRound,
  PracticeStart,
  PracticeSubmit,
} from "@/lib/types";

const MAX_ROUNDS = 3; // 与 src.mock.MAX_ROUNDS 对齐（0、1、2 三轮）
const LAST_ROUND = MAX_ROUNDS - 1;

type Phase = "idle" | "started" | "scored" | "complete";

interface ChatMsg {
  role: "system" | "user";
  content: string;
}

export default function PracticePanel() {
  const [phase, setPhase] = useState<Phase>("idle");
  const [start, setStart] = useState<PracticeStart | null>(null);
  const [roundNo, setRoundNo] = useState(0);
  const [rounds, setRounds] = useState<PracticeRound[]>([]);
  const [result, setResult] = useState<PracticeSubmit | null>(null);
  const [complete, setComplete] = useState<PracticeComplete | null>(null);
  const [answer, setAnswer] = useState("");
  const [msgs, setMsgs] = useState<ChatMsg[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const pushMsg = (m: ChatMsg) => setMsgs((prev) => [...prev, m]);

  async function begin() {
    setBusy(true);
    setError("");
    try {
      const s = await startPractice();
      setStart(s);
      setRoundNo(0);
      setRounds([]);
      setResult(null);
      setComplete(null);
      setAnswer("");
      setMsgs([
        {
          role: "system",
          content: `【${s.type} · ${s.max_score ?? "?"} 分】${s.question}\n\n📄 给定材料：\n${s.material}`,
        },
        {
          role: "system",
          content: `推荐理由：${s.recommend_reason || "按薄弱档案推荐"}${
            s.focus ? `\n本轮焦点：${s.focus}` : ""
          }\n\n请作答（第 1 轮，共 ${MAX_ROUNDS} 轮机会）：`,
        },
      ]);
      setPhase("started");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "推题失败");
    } finally {
      setBusy(false);
    }
  }

  async function submit() {
    if (!start || !answer.trim()) return;
    setBusy(true);
    setError("");
    const myAnswer = answer.trim();
    try {
      const r = await submitPractice(start.question_id, myAnswer, roundNo);
      setRounds((prev) => [
        ...prev,
        {
          round_no: roundNo,
          answer: myAnswer,
          hit_ids: r.hit_ids,
          miss_ids: r.miss_ids,
          hit_ratio: r.hit_ratio,
          guided_point_ids: r.guidance.map((g) => g.point_id),
        },
      ]);
      setResult(r);
      pushMsg({ role: "user", content: myAnswer });
      setAnswer("");
      setPhase("scored");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "提交失败");
    } finally {
      setBusy(false);
    }
  }

  async function finish() {
    if (!start) return;
    setBusy(true);
    setError("");
    try {
      const r = await completePractice(start.question_id, rounds);
      setComplete(r);
      pushMsg({ role: "system", content: "作答已回流档案：命中/漏点计入薄弱点档案，明天自动进入「今日提醒」。" });
      setPhase("complete");
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "回流失败");
    } finally {
      setBusy(false);
    }
  }

  const showFinish = result !== null && (result.passed || roundNo >= LAST_ROUND);
  const canSubmit = phase === "started" || (phase === "scored" && result && !result.passed && roundNo < LAST_ROUND);

  return (
    <div className="p-5 flex flex-col h-full min-h-[540px]">
      {/* 状态条 */}
      <div className="flex items-center justify-between mb-4">
        <div>
          <h2 className="text-base font-semibold text-zinc-900">申论练习</h2>
          <p className="text-[11px] text-zinc-500">提交即评分 → 漏点引导 → 达标回流档案</p>
        </div>
        <div className="flex items-center gap-2">
          {start && (
            <span className="text-[11px] text-zinc-500 bg-zinc-100 rounded-full px-2.5 py-1">
              第 {roundNo + 1} 轮 / 共 {MAX_ROUNDS} 轮
            </span>
          )}
          {phase === "idle" && (
            <button
              onClick={begin}
              disabled={busy}
              className="px-3.5 py-2 rounded-lg bg-indigo-600 text-white text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 transition-colors"
            >
              {busy ? "推题中…" : "开始练习"}
            </button>
          )}
        </div>
      </div>

      {error && (
        <div className="mb-3 rounded-xl border border-red-200 bg-red-50 px-4 py-2.5 text-sm text-red-600">
          {error}
        </div>
      )}

      {/* 消息流 */}
      <div className="flex-1 space-y-3 overflow-y-auto pr-1">
        {msgs.map((m, i) => (
          <div key={i} className={`flex ${m.role === "user" ? "justify-end" : "justify-start"}`}>
            <div
              className={`max-w-[85%] rounded-xl px-4 py-3 text-sm whitespace-pre-wrap ${
                m.role === "user"
                  ? "bg-indigo-600 text-white"
                  : "bg-white border border-zinc-200 shadow-sm text-zinc-800"
              }`}
            >
              {m.content}
            </div>
          </div>
        ))}

        {/* 评分卡 */}
        {result && phase === "scored" && (
          <div className="rounded-xl border border-zinc-200 bg-white shadow-sm overflow-hidden">
            <div className="px-4 py-3 flex items-center justify-between border-b border-zinc-100">
              <p className="text-sm font-semibold text-zinc-900">
                第 {roundNo + 1} 轮评分
              </p>
              <span
                className={`text-xs font-semibold px-2.5 py-1 rounded-full ${
                  result.passed ? "bg-emerald-50 text-emerald-700" : "bg-red-50 text-red-600"
                }`}
              >
                {result.passed ? `✓ 达标 ${Math.round(result.hit_ratio * 100)}%` : `✗ 未达标 ${Math.round(result.hit_ratio * 100)}%`}
              </span>
            </div>
            <div className="px-4 py-3 space-y-2.5">
              <div>
                <p className="text-[11px] text-zinc-400 mb-1">命中（{result.hits.length}）</p>
                <div className="flex flex-wrap gap-1.5">
                  {result.hits.length === 0 && <span className="text-xs text-zinc-300">无</span>}
                  {result.hits.map((h) => (
                    <span key={h} className="text-xs bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-full px-2 py-0.5">
                      {h}
                    </span>
                  ))}
                </div>
              </div>
              <div>
                <p className="text-[11px] text-zinc-400 mb-1">漏点（{result.misses.length}）</p>
                <div className="flex flex-wrap gap-1.5">
                  {result.misses.length === 0 && <span className="text-xs text-zinc-300">无</span>}
                  {result.misses.map((m) => (
                    <span key={m} className="text-xs bg-red-50 text-red-600 border border-red-200 rounded-full px-2 py-0.5">
                      {m}
                    </span>
                  ))}
                </div>
              </div>

              {/* 引导 */}
              {result.guidance.length > 0 && (
                <div className="rounded-lg bg-amber-50 border border-amber-200 px-3 py-2.5 space-y-2">
                  <p className="text-[11px] font-semibold text-amber-700">逼近引导——补全这些点，再来一轮：</p>
                  {result.guidance.map((g) => (
                    <div key={g.point_id} className="text-xs text-amber-900">
                      <span className="font-medium">{g.point}</span>
                      <span className="text-amber-600"> — {g.hint}</span>
                    </div>
                  ))}
                </div>
              )}

              {result.passed && (
                <p className="text-xs text-emerald-700">达标！点击「完成回流」把本轮轨迹写入档案。</p>
              )}
              {!result.passed && roundNo >= LAST_ROUND && (
                <p className="text-xs text-red-600">已到轮次上限——点击「完成回流」记录薄弱点，改天再战。</p>
              )}
            </div>
          </div>
        )}

        {/* 完成卡 */}
        {complete && phase === "complete" && (
          <div className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">
            档案已更新{complete.weak_added > 0 ? `，新增 ${complete.weak_added} 个薄弱点` : ""}。练下一道？
            <button
              onClick={begin}
              disabled={busy}
              className="ml-3 px-3 py-1.5 rounded-lg bg-emerald-600 text-white text-xs font-medium hover:bg-emerald-700 disabled:opacity-50 transition-colors"
            >
              再练一道 →
            </button>
          </div>
        )}
      </div>

      {/* 作答区 */}
      {(canSubmit || showFinish) && (
        <div className="mt-4 pt-4 border-t border-zinc-100">
          {canSubmit && (
            <>
              <textarea
                value={answer}
                onChange={(e) => setAnswer(e.target.value)}
                placeholder={
                  result && !result.passed && roundNo < LAST_ROUND
                    ? `补充作答——只写漏掉的点也可以（第 ${roundNo + 2} 轮）`
                    : "在此作答…"
                }
                rows={4}
                className="w-full rounded-xl border border-zinc-200 bg-white px-3.5 py-2.5 text-sm text-zinc-800 outline-none focus:ring-2 focus:ring-indigo-500/40 focus:border-indigo-400 placeholder:text-zinc-300"
              />
              <div className="mt-2 flex justify-end">
                <button
                  onClick={submit}
                  disabled={busy || !answer.trim()}
                  className="px-4 py-2 rounded-lg bg-indigo-600 text-white text-sm font-medium hover:bg-indigo-700 disabled:opacity-50 transition-colors"
                >
                  {busy ? "评分中…" : "提交作答"}
                </button>
              </div>
            </>
          )}
          {showFinish && (
            <div className="flex justify-end">
              <button
                onClick={finish}
                disabled={busy}
                className="px-4 py-2 rounded-lg bg-zinc-900 text-white text-sm font-medium hover:bg-zinc-700 disabled:opacity-50 transition-colors"
              >
                {busy ? "回流中…" : "完成回流 →"}
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
